function renderSlots(){document.querySelectorAll('.np-slot').forEach(g=>{const i=+g.dataset.slot,v=placed[i],t=g.querySelector('text'),where=g.dataset.position;g.querySelectorAll('.projection-label').forEach(x=>x.remove());if(v){t.textContent='';groupText(g,{x:+g.dataset.labelX,y:+g.dataset.labelY},v.label,+g.dataset.ux)}else t.textContent='+';g.classList.toggle('filled',!!v);g.setAttribute('aria-label',v?`${where}: ${v.label}. Select to remove.`:`Empty ${where}`)})}
